={{
  (() => {
    const content =
      $('TelePilot Trigger').first().json.message?.content ?? {};

    // PDF, DOCX, XLSX, ZIP и изображения,
    // отправленные в Telegram как файл
    const documentFile = content.document?.document;

    if (documentFile?.id) {
      return documentFile.id;
    }

    // Изображение, отправленное как обычное фото
    const photoSizes = content.photo?.sizes ?? [];

    if (photoSizes.length > 0) {
      // Выбираем самый большой доступный вариант фотографии
      const largestPhoto = photoSizes.reduce((largest, current) => {
        const currentFile = current?.photo;

        if (!currentFile?.id) {
          return largest;
        }

        const currentSize = Number(
          currentFile.size ??
          currentFile.expected_size ??
          0
        );

        const largestSize = Number(
          largest?.size ??
          largest?.expected_size ??
          0
        );

        return currentSize >= largestSize
          ? currentFile
          : largest;
      }, null);

      if (largestPhoto?.id) {
        return largestPhoto.id;
      }
    }

    throw new Error(
      'Не удалось определить File ID документа или фотографии'
    );
  })()
}}

