const fs = require('fs');
const path = require('path');

const item = $input.first();

// Поддерживаем новую и старую структуру ответа Download file
const filePath =
  item.json.file?.local?.path ??
  item.json.local?.path;

if (!filePath) {
  throw new Error(
    'TelePilot не вернул путь к файлу: file.local.path'
  );
}

if (!fs.existsSync(filePath)) {
  throw new Error(`Файл не найден по пути: ${filePath}`);
}

// Читаем скачанный файл
const buffer = fs.readFileSync(filePath);

// Максимальный размер — 100 МБ
const maxSize = 100 * 1024 * 1024;

if (buffer.length >= maxSize) {
  throw new Error(
    `Файл должен быть меньше 100 МБ. ` +
    `Полученный размер: ${(buffer.length / 1024 / 1024).toFixed(2)} МБ`
  );
}

// Исходное сообщение из TelePilot Trigger
const trigger =
  $('TelePilot Trigger').first().json;

const message = trigger.message ?? {};
const content = message.content ?? {};

// Документ, отправленный как файл
const document = content.document ?? {};

// Определяем имя файла
let fileName =
  document.file_name ??
  path.basename(filePath);

// Если имя определить не удалось
if (
  !fileName ||
  fileName === '.' ||
  fileName === path.sep
) {
  fileName = `telegram_file_${Date.now()}`;
}

// Определяем MIME-тип
let contentType =
  document.mime_type ??
  null;

// Если пришла обычная фотография, у неё может не быть file_name и mime_type
if (!contentType && content.photo) {
  contentType = 'image/jpeg';

  const extension = path.extname(fileName);

  if (!extension) {
    fileName = `telegram_photo_${Date.now()}.jpg`;
  }
}

// Запасное значение для остальных документов
if (!contentType) {
  const extension = path.extname(fileName).toLowerCase();

  const mimeTypes = {
    '.pdf': 'application/pdf',
    '.csv': 'text/csv',
    '.txt': 'text/plain',
    '.json': 'application/json',
    '.xml': 'application/xml',

    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.png': 'image/png',
    '.webp': 'image/webp',

    '.doc': 'application/msword',
    '.docx':
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',

    '.xls': 'application/vnd.ms-excel',
    '.xlsx':
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',

    '.ppt': 'application/vnd.ms-powerpoint',
    '.pptx':
      'application/vnd.openxmlformats-officedocument.presentationml.presentation',

    '.zip': 'application/zip',
    '.rar': 'application/vnd.rar',
    '.7z': 'application/x-7z-compressed',
  };

  contentType =
    mimeTypes[extension] ??
    'application/octet-stream';
}

return [
  {
    json: {
      ...item.json,

      // Это поле передаётся в Convert to File
      file_base64: buffer.toString('base64'),

      file_name: fileName,
      content_type: contentType,

      actual_file_size: buffer.length,
      actual_file_size_mb: Number(
        (buffer.length / 1024 / 1024).toFixed(2)
      ),

      telegram_message_id:
        message.id ?? null,

      telegram_user_id:
        message.sender_id?.user_id ?? null,

      telegram_chat_id:
        message.chat_id ?? null,

      local_path: filePath,
    },
  },
];

