const allowedStatuses = [
  'wait_admin',
  'send_message',
  'finish',
];

function parseAiResponse(value) {
  if (value === null || value === undefined) {
    throw new Error('AI Agent вернул пустой ответ');
  }

  if (typeof value === 'object') {
    return value;
  }

  if (typeof value !== 'string') {
    throw new Error(
      `Неизвестный тип ответа AI Agent: ${typeof value}`
    );
  }

  const cleaned = value
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    return JSON.parse(cleaned);
  } catch (error) {
    const firstBrace = cleaned.indexOf('{');
    const lastBrace = cleaned.lastIndexOf('}');

    if (firstBrace === -1 || lastBrace === -1) {
      throw new Error(
        `В ответе AI Agent не найден JSON: ${cleaned}`
      );
    }

    const jsonFragment = cleaned.slice(
      firstBrace,
      lastBrace + 1
    );

    try {
      return JSON.parse(jsonFragment);
    } catch (parseError) {
      throw new Error(
        `Не удалось разобрать ответ AI Agent как JSON: ${jsonFragment}`
      );
    }
  }
}

let rawResponse =
  $json.output ??
  $json.response ??
  $json.text ??
  $json;

let parsed = parseAiResponse(rawResponse);

// Поддержка результата внутри поля output
if (
  parsed &&
  typeof parsed === 'object' &&
  parsed.output !== undefined &&
  parsed.status === undefined
) {
  parsed = parseAiResponse(parsed.output);
}

// Поддержка результата внутри поля response
if (
  parsed &&
  typeof parsed === 'object' &&
  parsed.response !== undefined &&
  parsed.status === undefined
) {
  parsed = parseAiResponse(parsed.response);
}

const status = String(parsed.status ?? '').trim();
const message = String(parsed.message ?? '').trim();
let result = String(parsed.result ?? '').trim();

if (!status) {
  throw new Error(
    'В ответе AI Agent отсутствует поле status'
  );
}

if (!allowedStatuses.includes(status)) {
  throw new Error(
    `Недопустимый статус AI Agent: ${status}`
  );
}

if (!message) {
  throw new Error(
    'В ответе AI Agent отсутствует поле message'
  );
}

// При продолжении диалога результат не нужен
if (status === 'send_message') {
  result = '';
}

// При ожидании администратора вопрос обязателен
if (status === 'wait_admin' && !result) {
  throw new Error(
    'AI Agent вернул статус wait_admin, но не сформировал вопрос для администратора в поле result'
  );
}

// При завершении итог обязателен
if (status === 'finish' && !result) {
  throw new Error(
    'AI Agent вернул статус finish, но не сформировал итог задачи в поле result'
  );
}

return {
  json: {
    ...$json,
    status,
    message,
    result,
  },
};

