  (() => {
    const now = $now.setZone('Europe/Moscow');

    const currentSeconds =
      now.hour * 3600 +
      now.minute * 60 +
      now.second;

    const startRaw = $if(
      $('Search task').isExecuted,
      $('Search task').first().json.start_bot,
      $if(
        $('Search task1').isExecuted,
        $('Search task1').first().json.start_bot,
        null
      )
    );

    const finishRaw = $if(
      $('Search task').isExecuted,
      $('Search task').first().json.stop_bot,
      $if(
        $('Search task1').isExecuted,
        $('Search task1').first().json.stop_bot,
        null
      )
    );

    const start = Number(startRaw);
    const finish = Number(finishRaw);

    // Если ни одна нода не выполнилась
    // или время указано некорректно
    if (
      startRaw === null ||
      finishRaw === null ||
      !Number.isFinite(start) ||
      !Number.isFinite(finish)
    ) {
      return false;
    }

    // Одинаковое время — разрешено круглосуточно
    if (start === finish) {
      return true;
    }

    // Обычный период, например 09:00–19:00
    if (start < finish) {
      return (
        currentSeconds >= start &&
        currentSeconds < finish
      );
    }

    // Ночной период, например 22:00–06:00
    return (
      currentSeconds >= start ||
      currentSeconds < finish
    );
  })()
}}

