const record = $input.first().json;

const uploadResult =
  $('Upload an asset from file data').first().json;

// Берём защищённую ссылку Cloudinary.
// Если secure_url отсутствует, используем обычный url.
const newUrl =
  uploadResult.secure_url ??
  uploadResult.url;

if (!newUrl) {
  throw new Error(
    'Нода Upload an asset from file data не вернула secure_url или url'
  );
}

// Текущее содержимое docs_url из Airtable
const currentValue = record.docs_url ?? '';

let urls = [];

// Поддержка случая, если поле уже является массивом
if (Array.isArray(currentValue)) {
  urls = currentValue
    .map(value => {
      if (typeof value === 'string') {
        return value.trim();
      }

      return value?.url?.trim() ?? '';
    })
    .filter(Boolean);
}

// Поддержка текстового поля Airtable
if (typeof currentValue === 'string') {
  const trimmed = currentValue.trim();

  if (trimmed) {
    // Сначала пробуем прочитать значение как JSON-массив
    try {
      const parsed = JSON.parse(trimmed);

      if (Array.isArray(parsed)) {
        urls = parsed
          .map(value => {
            if (typeof value === 'string') {
              return value.trim();
            }

            return value?.url?.trim() ?? '';
          })
          .filter(Boolean);
      } else {
        urls = [trimmed];
      }
    } catch {
      // Обычный текст: одна ссылка на строку.
      // Также поддерживаются запятые и точки с запятой.
      urls = trimmed
        .split(/[\r\n,;]+/)
        .map(value => value.trim())
        .filter(Boolean);
    }
  }
}

// Добавляем новую ссылку
urls.push(newUrl.trim());

// Удаляем пустые значения и повторяющиеся ссылки
const uniqueUrls = [
  ...new Set(
    urls.filter(url => url && /^https?:\/\//i.test(url))
  ),
];

// Сохраняем ссылки в Airtable:
// каждая ссылка будет находиться на отдельной строке
const docsUrl = uniqueUrls.join('\n');

return [
  {
    json: {
      ...record,

      docs_url: docsUrl,

      // Дополнительные поля для проверки
      added_doc_url: newUrl,
      docs_count: uniqueUrls.length,
    },
  },
];
